insert into public.species (slug,name,latin,category_id,kind,difficulty,temperament,description,facts,keywords,is_rare,status) values
('apistogramma-agassizii','Agassiz Cüce Ciklet','Apistogramma agassizii','guney-amerika','fish','Orta','Bölgeci, görece barışçıl','Amazon havzasında geniş yayılışlı, erkekleri uzamış yüzgeçleri ve renkli formlarıyla tanınan cüce ciklettir. Yaprak çürüntüsü ve saklanma alanları bulunan yumuşak sularda iyi gelişir.','[["Yetişkin boy", "7,5 cm"], ["Sıcaklık", "22–29 °C"], ["pH", "4.0–7.0"], ["Min. akvaryum", "60 L"], ["Huy", "Bölgeci, görece barışçıl"], ["Beslenme", "Omnivor, küçük omurgasız ağırlıklı"], ["Üreme", "Mağara yumurtlayıcısı"], ["Köken", "Güney Amerika"], ["Özellikler", "Cüce Ciklet, Renkli"]]'::jsonb,array['agassiz cüce ciklet','agassizii','apistogramma agassizii','agassiz apisto','agassizi']::text[],false,'published'),
('apistogramma-borellii','Borelli Cüce Ciklet','Apistogramma borellii','guney-amerika','fish','Kolay','Görece barışçıl, bölgeci','Küçük yapılı ve birçok Apistogramma''ya göre daha serin suyu tolere eden zarif bir türdür. Erkekler mavi-sarı tonlar gösterebilir.','[["Yetişkin boy", "6,5 cm"], ["Sıcaklık", "20–27 °C"], ["pH", "5.0–7.5"], ["Min. akvaryum", "50 L"], ["Huy", "Görece barışçıl, bölgeci"], ["Beslenme", "Omnivor, küçük omurgasız ağırlıklı"], ["Üreme", "Mağara yumurtlayıcısı"], ["Köken", "Güney Amerika"], ["Özellikler", "Cüce Ciklet, Barışçıl"]]'::jsonb,array['borelli cüce ciklet','borellii','apistogramma borellii','umbrella cichlid','borelli apisto']::text[],false,'published'),
('apistogramma-macmasteri','Kakadu dışı Macmasteri','Apistogramma macmasteri','guney-amerika','fish','Orta','Bölgeci','Orinoco havzasından gelen, erkekleri kırmızı ve turuncu yüzgeç detaylarıyla dikkat çeken bir cüce ciklettir. Üreme döneminde dişi mağara çevresini güçlü biçimde savunur.','[["Yetişkin boy", "7 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "5.5–7.0"], ["Min. akvaryum", "60 L"], ["Huy", "Bölgeci"], ["Beslenme", "Omnivor, küçük omurgasız ağırlıklı"], ["Üreme", "Mağara yumurtlayıcısı"], ["Köken", "Güney Amerika"], ["Özellikler", "Cüce Ciklet, Renkli"]]'::jsonb,array['kakadu dışı macmasteri','macmasteri','apistogramma macmasteri','macmaster apisto','red shoulder apisto']::text[],false,'published'),
('apistogramma-baenschi','İnka Cüce Ciklet','Apistogramma baenschi','guney-amerika','fish','Orta','Bölgeci','Peru kökenli, erkekleri turuncu-kırmızı yüzgeçleri ve belirgin desenleriyle tanınan küçük bir Apistogramma''dır. Yumuşak ve asidik su üreme için avantaj sağlar.','[["Yetişkin boy", "6 cm"], ["Sıcaklık", "22–27 °C"], ["pH", "4.0–6.5"], ["Min. akvaryum", "60 L"], ["Huy", "Bölgeci"], ["Beslenme", "Omnivor, küçük omurgasız ağırlıklı"], ["Üreme", "Mağara yumurtlayıcısı"], ["Köken", "Güney Amerika"], ["Özellikler", "Cüce Ciklet, Nadir Tür"]]'::jsonb,array['inka cüce ciklet','baenschi','apistogramma baenschi','inka apisto','inka 50']::text[],true,'published'),
('apistogramma-panduro','Panduro Cüce Ciklet','Apistogramma panduro','guney-amerika','fish','Orta','Bölgeci','Peru''nun siyah su sistemlerinden gelen, belirgin cinsel dimorfizm gösteren bir cüce ciklettir. Sakin tank arkadaşları ve bol saklanma alanı tercih eder.','[["Yetişkin boy", "7 cm"], ["Sıcaklık", "23–29 °C"], ["pH", "4.0–6.5"], ["Min. akvaryum", "60 L"], ["Huy", "Bölgeci"], ["Beslenme", "Omnivor, küçük omurgasız ağırlıklı"], ["Üreme", "Mağara yumurtlayıcısı"], ["Köken", "Güney Amerika"], ["Özellikler", "Cüce Ciklet, Siyah Su"]]'::jsonb,array['panduro cüce ciklet','panduro','apistogramma panduro','pandurini','panduro apisto']::text[],true,'published'),
('apistogramma-nijsseni','Nijsseni Cüce Ciklet','Apistogramma nijsseni','guney-amerika','fish','Zor','Bölgeci','Dişisinin sarı-siyah üreme rengi ve erkeğin mavi tonlarıyla dikkat çeken Peru kökenli bir türdür. Yumuşak ve asidik su koşullarında daha başarılıdır.','[["Yetişkin boy", "7 cm"], ["Sıcaklık", "23–29 °C"], ["pH", "4.0–6.5"], ["Min. akvaryum", "60 L"], ["Huy", "Bölgeci"], ["Beslenme", "Omnivor, küçük omurgasız ağırlıklı"], ["Üreme", "Mağara yumurtlayıcısı"], ["Köken", "Güney Amerika"], ["Özellikler", "Cüce Ciklet, Siyah Su"]]'::jsonb,array['nijsseni cüce ciklet','nijsseni','apistogramma nijsseni','panda apisto','nijssen apisto']::text[],true,'published'),
('apistogramma-bitaeniata','Bitaeniata Cüce Ciklet','Apistogramma bitaeniata','guney-amerika','fish','Zor','Bölgeci','İki belirgin yatay çizgisi ve uzun yüzgeçleriyle tanınan Amazon cüce cikletidir. Siyah suya uyumlu popülasyonlarında düşük pH önemli olabilir.','[["Yetişkin boy", "7 cm"], ["Sıcaklık", "23–29 °C"], ["pH", "4.0–6.5"], ["Min. akvaryum", "60 L"], ["Huy", "Bölgeci"], ["Beslenme", "Omnivor, küçük omurgasız ağırlıklı"], ["Üreme", "Mağara yumurtlayıcısı"], ["Köken", "Güney Amerika"], ["Özellikler", "Cüce Ciklet, Siyah Su"]]'::jsonb,array['bitaeniata cüce ciklet','bitaeniata','apistogramma bitaeniata','two striped apisto','iki çizgili apisto']::text[],true,'published'),
('apistogramma-mendezi','Mendezi Cüce Ciklet','Apistogramma mendezi','guney-amerika','fish','Zor','Bölgeci','Rio Negro sisteminden gelen, ince yapılı ve gösterişli erkeklere sahip bir siyah su cüce cikletidir. Çok yumuşak, asidik su ve oturmuş akvaryum ister.','[["Yetişkin boy", "7 cm"], ["Sıcaklık", "24–29 °C"], ["pH", "4.0–6.0"], ["Min. akvaryum", "60 L"], ["Huy", "Bölgeci"], ["Beslenme", "Omnivor, küçük omurgasız ağırlıklı"], ["Üreme", "Mağara yumurtlayıcısı"], ["Köken", "Güney Amerika"], ["Özellikler", "Cüce Ciklet, Nadir Tür"]]'::jsonb,array['mendezi cüce ciklet','mendezi','apistogramma mendezi','a220','rio negro apisto']::text[],true,'published'),
('apistogramma-steindachneri','Steindachneri Cüce Ciklet','Apistogramma steindachneri','guney-amerika','fish','Orta','Bölgeci','Guyana ve çevresindeki drenajlardan gelen, görece iri ve dayanıklı bir Apistogramma''dır. Erkekler geniş bölge tutabilir.','[["Yetişkin boy", "8 cm"], ["Sıcaklık", "23–29 °C"], ["pH", "5.0–7.0"], ["Min. akvaryum", "70 L"], ["Huy", "Bölgeci"], ["Beslenme", "Omnivor"], ["Üreme", "Mağara yumurtlayıcısı"], ["Köken", "Güney Amerika"], ["Özellikler", "Cüce Ciklet, Bölgeci"]]'::jsonb,array['steindachneri cüce ciklet','steindachneri','apistogramma steindachneri','steindachner apisto','guyana apisto']::text[],true,'published'),
('aequidens-diadema','Royal Acara / Diadema','Aequidens diadema','guney-amerika','fish','Orta','Yarı agresif, eş tutunca bölgeci','Orinoco havzasına ait, erişkinlerinde mavi-yeşil ışıltılar ve güçlü ebeveyn davranışı görülen orta boy bir ciklettir. Çiftler üreme döneminde belirgin biçimde bölgeci olur.','[["Yetişkin boy", "15 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "5.0–7.0"], ["Min. akvaryum", "180 L"], ["Huy", "Yarı agresif, eş tutunca bölgeci"], ["Beslenme", "Omnivor"], ["Üreme", "Substrat yumurtlayıcısı, ebeveyn bakımı"], ["Köken", "Güney Amerika"], ["Özellikler", "Ebeveyn Bakımı, Nadir Tür"]]'::jsonb,array['royal acara / diadema','aequidens diadema','diadema','royal acara','royal akara']::text[],true,'published'),
('andinoacara-pulcher','Mavi Acara','Andinoacara pulcher','guney-amerika','fish','Kolay','Yarı agresif','Mavi-yeşil metalik renkleri ve görece uyumlu karakteriyle popüler bir orta boy ciklettir. Eş tutan bireyler yumurta ve yavruları birlikte korur.','[["Yetişkin boy", "15 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "150 L"], ["Huy", "Yarı agresif"], ["Beslenme", "Omnivor"], ["Üreme", "Substrat yumurtlayıcısı, çift ebeveyn bakımı"], ["Köken", "Güney Amerika"], ["Özellikler", "Ebeveyn Bakımı, Dayanıklı"]]'::jsonb,array['andinoacara pulcher','blue acara','mavi acara','mavi akara']::text[],false,'published'),
('andinoacara-rivulatus','Green Terror','Andinoacara rivulatus','guney-amerika','fish','Orta','Agresif, bölgeci','Erkeklerde turuncu-beyaz yüzgeç kenarları ve güçlü gövde yapısıyla tanınır. Büyük ve bölgeci olduğundan geniş akvaryum ve dikkatli eşleştirme gerekir.','[["Yetişkin boy", "20 cm"], ["Sıcaklık", "20–26 °C"], ["pH", "6.0–8.0"], ["Min. akvaryum", "250 L"], ["Huy", "Agresif, bölgeci"], ["Beslenme", "Omnivor"], ["Üreme", "Substrat yumurtlayıcısı, çift ebeveyn bakımı"], ["Köken", "Güney Amerika"], ["Özellikler", "Agresif, İri Yapılı"]]'::jsonb,array['andinoacara rivulatus','green terror','gold saum','yeşil terör']::text[],false,'published'),
('biotodoma-cupido','Cupid Ciklet','Biotodoma cupido','guney-amerika','fish','Orta','Barışçıl, sosyal','Amazon havzasının sakin kumluk bölgelerinde yaşayan zarif bir toprak yiyen ciklettir. Grup hâlinde ve ince kum tabanlı geniş akvaryumda daha doğal davranır.','[["Yetişkin boy", "10 cm"], ["Sıcaklık", "24–29 °C"], ["pH", "5.0–7.0"], ["Min. akvaryum", "200 L"], ["Huy", "Barışçıl, sosyal"], ["Beslenme", "Omnivor, küçük bentik omurgasızlar"], ["Üreme", "Substrat yumurtlayıcısı"], ["Köken", "Güney Amerika"], ["Özellikler", "Barışçıl, Kum Eleyen"]]'::jsonb,array['biotodoma cupido','cupid cichlid','cupido','cupid ciklet']::text[],true,'published'),
('biotodoma-wavrini','Orinoco Eartheater','Biotodoma wavrini','guney-amerika','fish','Zor','Barışçıl, sosyal','Orinoco ve Rio Negro sistemlerinde yaşayan, yumuşak-asidik suyu seven zarif bir toprak yiyendir. Grup hâlinde tutulması ve geniş kum alanı sağlanması önerilir.','[["Yetişkin boy", "10 cm"], ["Sıcaklık", "24–30 °C"], ["pH", "4.0–6.5"], ["Min. akvaryum", "250 L"], ["Huy", "Barışçıl, sosyal"], ["Beslenme", "Omnivor, küçük bentik omurgasızlar"], ["Üreme", "Substrat yumurtlayıcısı"], ["Köken", "Güney Amerika"], ["Özellikler", "Barışçıl, Siyah Su"]]'::jsonb,array['biotodoma wavrini','wavrini','orinoco eartheater','biotodoma']::text[],true,'published'),
('biotoecus-dicentrarchus','Dicentrarchus','Biotoecus dicentrarchus','guney-amerika','fish','Zor','Barışçıl, narin','Çok küçük, narin yapılı ve yumuşak-asidik suya uyumlu bir Geophaginae üyesidir. İnce kum, yaprak çürüntüsü ve sakin tank arkadaşlarıyla en iyi sonucu verir.','[["Yetişkin boy", "5 cm"], ["Sıcaklık", "25–30 °C"], ["pH", "4.0–6.5"], ["Min. akvaryum", "50 L"], ["Huy", "Barışçıl, narin"], ["Beslenme", "Mikroavcı, küçük omurgasız"], ["Üreme", "Substrat yumurtlayıcısı"], ["Köken", "Güney Amerika"], ["Özellikler", "Cüce Ciklet, Nadir Tür"]]'::jsonb,array['biotoecus dicentrarchus','dicentrarchus','biotoecus','dwarf eartheater']::text[],true,'published'),
('crenicara-punctulatum','Cupido Crenicara','Crenicara punctulatum','guney-amerika','fish','Orta','Barışçıl','Yaprak çürüntülü ve kumluk alanlarda yaşayan, sakin karakterli küçük bir geophagine ciklettir. Benekli deseni ve narin yapısıyla topluluk tanklarında dikkat çeker.','[["Yetişkin boy", "12 cm"], ["Sıcaklık", "24–29 °C"], ["pH", "5.0–7.0"], ["Min. akvaryum", "120 L"], ["Huy", "Barışçıl"], ["Beslenme", "Omnivor, küçük omurgasız ağırlıklı"], ["Üreme", "Substrat yumurtlayıcısı"], ["Köken", "Güney Amerika"], ["Özellikler", "Barışçıl, Benekli"]]'::jsonb,array['cupido crenicara','crenicara punctulatum','punctulatum','checkerboard cichlid','crenicara']::text[],true,'published'),
('dicrossus-filamentosus','Dama Cüce Ciklet','Dicrossus filamentosus','guney-amerika','fish','Zor','Barışçıl, üremede bölgeci','Rio Negro ve Orinoco çevresinin çok yumuşak siyah sularında yaşayan ince yapılı bir cüce ciklettir. Dama desenli gövdesi ve uzayan kuyruk ışınlarıyla tanınır.','[["Yetişkin boy", "9 cm"], ["Sıcaklık", "26–30 °C"], ["pH", "4.0–6.5"], ["Min. akvaryum", "80 L"], ["Huy", "Barışçıl, üremede bölgeci"], ["Beslenme", "Mikroavcı"], ["Üreme", "Açık substrata yumurtlar, ebeveyn bakımı"], ["Köken", "Güney Amerika"], ["Özellikler", "Siyah Su, Nadir Tür"]]'::jsonb,array['dama cüce ciklet','dicrossus filamentosus','checkerboard cichlid','filamentosus','dama ciklet']::text[],true,'published'),
('geophagus-altifrons','Altifrons Eartheater','Geophagus altifrons','guney-amerika','fish','Orta','Barışçıl, sosyal','Amazon havzasının iri, gösterişli toprak yiyenlerinden biridir. Grup hâlinde tutulmalı ve doğal kum eleme davranışı için geniş ince kum alanı sağlanmalıdır.','[["Yetişkin boy", "23 cm"], ["Sıcaklık", "26–32 °C"], ["pH", "4.8–7.0"], ["Min. akvaryum", "400 L"], ["Huy", "Barışçıl, sosyal"], ["Beslenme", "Omnivor, bentik omurgasız ağırlıklı"], ["Üreme", "Ağızda kuluçka/larvofil ebeveyn bakımı"], ["Köken", "Güney Amerika"], ["Özellikler", "Kum Eleyen, Sürü Balığı"]]'::jsonb,array['altifrons eartheater','geophagus altifrons','altifrons','eartheater','toprak yiyen']::text[],false,'published'),
('geophagus-abalios','Abalios Eartheater','Geophagus abalios','guney-amerika','fish','Orta','Barışçıl, sosyal','Orinoco sisteminden gelen iri bir toprak yiyendir ve ticarette sıkça başka Geophagus adlarıyla karıştırılır. Grup hâlinde, geniş kum tabanlı tanklarda tutulmalıdır.','[["Yetişkin boy", "20 cm"], ["Sıcaklık", "26–32 °C"], ["pH", "4.0–7.0"], ["Min. akvaryum", "350 L"], ["Huy", "Barışçıl, sosyal"], ["Beslenme", "Omnivor, bentik omurgasız ağırlıklı"], ["Üreme", "Ağızda kuluçka/ebeveyn bakımı"], ["Köken", "Güney Amerika"], ["Özellikler", "Kum Eleyen, Sürü Balığı"]]'::jsonb,array['abalios eartheater','geophagus abalios','abalios','eartheater','orinoco geophagus']::text[],true,'published'),
('geophagus-sveni','Sveni Eartheater','Geophagus sveni','guney-amerika','fish','Orta','Barışçıl, sosyal','Tocantins havzasından gelen, kırmızı-turuncu yüzgeç detaylarıyla popülerleşen bir Geophagus''tur. Grup hâlinde tutulması ve geniş kum tabanı önemlidir.','[["Yetişkin boy", "20 cm"], ["Sıcaklık", "25–30 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "350 L"], ["Huy", "Barışçıl, sosyal"], ["Beslenme", "Omnivor, bentik omurgasız ağırlıklı"], ["Üreme", "Ağızda kuluçka/ebeveyn bakımı"], ["Köken", "Güney Amerika"], ["Özellikler", "Kum Eleyen, Renkli"]]'::jsonb,array['sveni eartheater','geophagus sveni','sveni','red head sveni','tocantins geophagus']::text[],false,'published'),
('geophagus-pyrocephalus','Tapajos Red Head','Geophagus pyrocephalus','guney-amerika','fish','Orta','Barışçıl, sosyal','Rio Tapajós kökenli kırmızı başlı Geophagus grubunun bilimsel olarak tanımlanmış türüdür. Erkeklerde belirgin kırmızı baş ve uzayan yüzgeçler görülür.','[["Yetişkin boy", "18 cm"], ["Sıcaklık", "24–30 °C"], ["pH", "5.5–7.5"], ["Min. akvaryum", "300 L"], ["Huy", "Barışçıl, sosyal"], ["Beslenme", "Omnivor, kum eleyici"], ["Üreme", "Ağızda kuluçka/ebeveyn bakımı"], ["Köken", "Güney Amerika"], ["Özellikler", "Kum Eleyen, Renkli"]]'::jsonb,array['geophagus pyrocephalus','red head tapajos','tapajos red head','kırmızı kafa geophagus']::text[],false,'published'),
('geophagus-winemilleri','Winemilleri Eartheater','Geophagus winemilleri','guney-amerika','fish','Orta','Barışçıl, sosyal','Orinoco havzasından gelen iri ve gösterişli bir Geophagus''tur. Yetişkinlerde metalik renkler ve belirgin yan leke görülür; geniş kum tabanı ister.','[["Yetişkin boy", "20 cm"], ["Sıcaklık", "25–30 °C"], ["pH", "5.0–7.0"], ["Min. akvaryum", "350 L"], ["Huy", "Barışçıl, sosyal"], ["Beslenme", "Omnivor, kum eleyici"], ["Üreme", "Ağızda kuluçka/ebeveyn bakımı"], ["Köken", "Güney Amerika"], ["Özellikler", "Kum Eleyen, Nadir Tür"]]'::jsonb,array['winemilleri eartheater','geophagus winemilleri','winemilleri','orinoco geophagus','eartheater']::text[],true,'published'),
('geophagus-argyrostictus','Argyrostictus Eartheater','Geophagus argyrostictus','guney-amerika','fish','Zor','Barışçıl, sosyal','Rio Xingu''ya özgü, baş bölgesindeki desenleriyle ayırt edilen orta-iri bir Geophagus''tur. Temiz, oksijenli su ve geniş kum alanı ister.','[["Yetişkin boy", "18 cm"], ["Sıcaklık", "26–30 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "300 L"], ["Huy", "Barışçıl, sosyal"], ["Beslenme", "Omnivor, kum eleyici"], ["Üreme", "Ebeveyn bakımı"], ["Köken", "Güney Amerika"], ["Özellikler", "Kum Eleyen, Nadir Tür"]]'::jsonb,array['argyrostictus eartheater','geophagus argyrostictus','argyrostictus','xingu geophagus','eartheater']::text[],true,'published'),
('satanoperca-jurupari','Jurupari','Satanoperca jurupari','guney-amerika','fish','Zor','Barışçıl, sosyal','Amazon havzasında geniş yayılış gösteren, kumu sürekli eleyerek beslenen iri ve sakin bir ciklettir. Grup hâlinde ve çok geniş taban alanında tutulmalıdır.','[["Yetişkin boy", "19 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "5.5–7.5"], ["Min. akvaryum", "450 L"], ["Huy", "Barışçıl, sosyal"], ["Beslenme", "Omnivor, kum eleyici"], ["Üreme", "Ağızda kuluçka/ebeveyn bakımı"], ["Köken", "Güney Amerika"], ["Özellikler", "Kum Eleyen, Sürü Balığı"]]'::jsonb,array['satanoperca jurupari','jurupari','demon eartheater','satanoperca']::text[],false,'published'),
('satanoperca-leucosticta','Leucosticta Eartheater','Satanoperca leucosticta','guney-amerika','fish','Zor','Barışçıl, sosyal','Baş ve solungaç kapağındaki açık renkli beneklerle tanınan sakin bir Satanoperca''dır. İnce kum ve yüksek su kalitesi bakımın temelidir.','[["Yetişkin boy", "18 cm"], ["Sıcaklık", "25–30 °C"], ["pH", "5.0–7.5"], ["Min. akvaryum", "400 L"], ["Huy", "Barışçıl, sosyal"], ["Beslenme", "Omnivor, kum eleyici"], ["Üreme", "Ağızda kuluçka/ebeveyn bakımı"], ["Köken", "Güney Amerika"], ["Özellikler", "Kum Eleyen, Benekli"]]'::jsonb,array['leucosticta eartheater','satanoperca leucosticta','leucosticta','white spot eartheater','satanoperca']::text[],true,'published'),
('satanoperca-daemon','Daemon Eartheater','Satanoperca daemon','guney-amerika','fish','Zor','Barışçıl, sosyal','Uzayan yüzgeçleri ve yan tarafındaki koyu lekeleriyle çok gösterişli bir siyah su Satanoperca''sıdır. Su kalitesine hassas olduğundan deneyimli bakım ister.','[["Yetişkin boy", "25 cm"], ["Sıcaklık", "25–30 °C"], ["pH", "4.0–6.5"], ["Min. akvaryum", "500 L"], ["Huy", "Barışçıl, sosyal"], ["Beslenme", "Omnivor, kum eleyici"], ["Üreme", "Substrat/ebeveyn bakımı"], ["Köken", "Güney Amerika"], ["Özellikler", "Siyah Su, Nadir Tür"]]'::jsonb,array['daemon eartheater','satanoperca daemon','daemon','three spot eartheater','demon fish']::text[],true,'published'),
('satanoperca-acuticeps','Acuticeps Eartheater','Satanoperca acuticeps','guney-amerika','fish','Zor','Barışçıl, sosyal','Sivri baş profili ve üç koyu yan lekesiyle ayırt edilen Amazon kökenli bir Satanoperca''dır. Geniş kum tabanı ve oturmuş akvaryum gerektirir.','[["Yetişkin boy", "17 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "5.5–7.5"], ["Min. akvaryum", "400 L"], ["Huy", "Barışçıl, sosyal"], ["Beslenme", "Omnivor, kum eleyici"], ["Üreme", "Ebeveyn bakımı"], ["Köken", "Güney Amerika"], ["Özellikler", "Kum Eleyen, Nadir Tür"]]'::jsonb,array['acuticeps eartheater','satanoperca acuticeps','acuticeps','sharphead eartheater','satanoperca']::text[],true,'published'),
('heros-efasciatus','Severum','Heros efasciatus','guney-amerika','fish','Kolay','Yarı agresif','Disk biçimli gövdesi ve sakin sayılabilecek karakteriyle popüler büyük Güney Amerika cikletlerindendir. Üreme döneminde çiftler bölge savunur.','[["Yetişkin boy", "20 cm"], ["Sıcaklık", "24–29 °C"], ["pH", "5.5–7.5"], ["Min. akvaryum", "250 L"], ["Huy", "Yarı agresif"], ["Beslenme", "Omnivor, bitkisel materyal de tüketir"], ["Üreme", "Substrat yumurtlayıcısı, çift ebeveyn bakımı"], ["Köken", "Güney Amerika"], ["Özellikler", "Ebeveyn Bakımı, İri Yapılı"]]'::jsonb,array['heros efasciatus','severum','green severum','severum ciklet']::text[],false,'published'),
('heros-sp-rotkeil','Rotkeil Severum','Heros sp. ''Rotkeil''','guney-amerika','fish','Orta','Yarı agresif','Boyun ve omuz bölgesindeki kırmızı-turuncu renklenmeyle tanınan, Peru kökenli ticari/lokasyon formudur. Heros grubunun sakin ve gösterişli üyelerindendir.','[["Yetişkin boy", "20 cm"], ["Sıcaklık", "24–29 °C"], ["pH", "5.0–7.0"], ["Min. akvaryum", "250 L"], ["Huy", "Yarı agresif"], ["Beslenme", "Omnivor"], ["Üreme", "Substrat yumurtlayıcısı, çift ebeveyn bakımı"], ["Köken", "Güney Amerika"], ["Özellikler", "Renkli, Ebeveyn Bakımı"]]'::jsonb,array['rotkeil severum','heros rotkeil','red shoulder severum','rotkeil']::text[],false,'published'),
('uaru-amphiacanthoides','Uaru','Uaru amphiacanthoides','guney-amerika','fish','Zor','Görece barışçıl, sosyal','Disk benzeri vücudu ve güçlü sosyal davranışıyla tanınan iri bir Amazon cikletidir. Gençler grup hâlinde tutulmalı; bitkisel içerikli beslenme önemlidir.','[["Yetişkin boy", "25 cm"], ["Sıcaklık", "26–30 °C"], ["pH", "5.0–7.0"], ["Min. akvaryum", "450 L"], ["Huy", "Görece barışçıl, sosyal"], ["Beslenme", "Omnivor, bitkisel ağırlıklı"], ["Üreme", "Substrat yumurtlayıcısı, çift ebeveyn bakımı"], ["Köken", "Güney Amerika"], ["Özellikler", "İri Yapılı, Sosyal"]]'::jsonb,array['uaru amphiacanthoides','uaru','triangle cichlid','amazon uaru']::text[],false,'published'),
('uaru-fernandezyepezi','Fernandezyepezi Uaru','Uaru fernandezyepezi','guney-amerika','fish','Zor','Barışçıl, sosyal','Orinoco üst havzasından gelen, U. amphiacanthoides''e göre çok daha nadir ve hassas bir Uaru türüdür. Yumuşak-asidik, sıcak ve çok temiz su ister.','[["Yetişkin boy", "25 cm"], ["Sıcaklık", "27–31 °C"], ["pH", "4.5–6.5"], ["Min. akvaryum", "500 L"], ["Huy", "Barışçıl, sosyal"], ["Beslenme", "Omnivor, bitkisel ağırlıklı"], ["Üreme", "Substrat yumurtlayıcısı, ebeveyn bakımı"], ["Köken", "Güney Amerika"], ["Özellikler", "Nadir Tür, İri Yapılı"]]'::jsonb,array['fernandezyepezi uaru','uaru fernandezyepezi','fernandezyepezi','panda uaru','orinoco uaru']::text[],true,'published'),
('mesonauta-festivus','Festivum','Mesonauta festivus','guney-amerika','fish','Kolay','Barışçıl–yarı agresif','Uzun gövdeli ve yukarı dönük ağız yapısıyla bitkili, sakin Amazon habitatlarına uyumlu bir ciklettir. Görece barışçıl yapısı topluluk akvaryumlarında avantaj sağlar.','[["Yetişkin boy", "15 cm"], ["Sıcaklık", "24–29 °C"], ["pH", "5.5–7.5"], ["Min. akvaryum", "180 L"], ["Huy", "Barışçıl–yarı agresif"], ["Beslenme", "Omnivor"], ["Üreme", "Substrat yumurtlayıcısı, ebeveyn bakımı"], ["Köken", "Güney Amerika"], ["Özellikler", "Barışçıl, Ebeveyn Bakımı"]]'::jsonb,array['mesonauta festivus','festivum','flag cichlid','festivus ciklet']::text[],false,'published'),
('cleithracara-maronii','Keyhole Ciklet','Cleithracara maronii','guney-amerika','fish','Kolay','Barışçıl','Utangaç ve barışçıl karakteriyle bilinen, yan tarafındaki anahtar deliği biçimli koyu lekeyle tanınan küçük-orta boy ciklettir.','[["Yetişkin boy", "10 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "5.5–7.5"], ["Min. akvaryum", "100 L"], ["Huy", "Barışçıl"], ["Beslenme", "Omnivor"], ["Üreme", "Substrat yumurtlayıcısı, çift ebeveyn bakımı"], ["Köken", "Güney Amerika"], ["Özellikler", "Barışçıl, Topluluk"]]'::jsonb,array['keyhole ciklet','cleithracara maronii','keyhole cichlid','maronii','anahtar deliği ciklet']::text[],false,'published'),
('laetacara-dorsigera','Kırmızı Göğüslü Acara','Laetacara dorsigera','guney-amerika','fish','Kolay','Barışçıl, üremede bölgeci','Üreme döneminde karın ve göğüs bölgesinde yoğun kırmızı renk geliştiren küçük, sakin bir ciklettir. Bitkili ve yaprak çürüntülü tanklara uygundur.','[["Yetişkin boy", "8 cm"], ["Sıcaklık", "20–28 °C"], ["pH", "5.0–7.5"], ["Min. akvaryum", "70 L"], ["Huy", "Barışçıl, üremede bölgeci"], ["Beslenme", "Omnivor"], ["Üreme", "Substrat yumurtlayıcısı, ebeveyn bakımı"], ["Köken", "Güney Amerika"], ["Özellikler", "Cüce Ciklet, Barışçıl"]]'::jsonb,array['kırmızı göğüslü acara','laetacara dorsigera','dorsigera','red breast acara','kırmızı göğüs acara']::text[],false,'published'),
('laetacara-curviceps','Curviceps Acara','Laetacara curviceps','guney-amerika','fish','Kolay','Barışçıl, üremede bölgeci','Küçük boyu, mavi ışıltıları ve sakin mizacıyla bitkili topluluk tanklarına uygun Güney Amerika cikletidir.','[["Yetişkin boy", "8 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "5.0–7.5"], ["Min. akvaryum", "70 L"], ["Huy", "Barışçıl, üremede bölgeci"], ["Beslenme", "Omnivor"], ["Üreme", "Substrat yumurtlayıcısı, ebeveyn bakımı"], ["Köken", "Güney Amerika"], ["Özellikler", "Cüce Ciklet, Barışçıl"]]'::jsonb,array['laetacara curviceps','curviceps','dwarf flag acara','curviceps acara']::text[],false,'published'),
('cichlasoma-portalegrense','Cupid Acara / Port Acara','Cichlasoma portalegrense','guney-amerika','fish','Kolay','Yarı agresif','Dayanıklı, orta boy ve ebeveyn bakım davranışı güçlü bir Güney Amerika cikletidir. Üreme döneminde bölgecilik artar.','[["Yetişkin boy", "15 cm"], ["Sıcaklık", "18–27 °C"], ["pH", "6.0–8.0"], ["Min. akvaryum", "150 L"], ["Huy", "Yarı agresif"], ["Beslenme", "Omnivor"], ["Üreme", "Substrat yumurtlayıcısı, çift ebeveyn bakımı"], ["Köken", "Güney Amerika"], ["Özellikler", "Dayanıklı, Ebeveyn Bakımı"]]'::jsonb,array['cupid acara / port acara','cichlasoma portalegrense','port acara','port cichlid','portalegrense']::text[],true,'published'),
('crenicichla-regani','Pike Cichlid Regani','Crenicichla regani','guney-amerika','fish','Orta','Yarı agresif, avcı','Crenicichla cinsinin küçük üyelerinden biridir. Uzun gövdesi ve avcı davranışıyla tipik pike ciklet görünümünü daha kompakt ölçekte sunar.','[["Yetişkin boy", "13 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "5.0–7.0"], ["Min. akvaryum", "150 L"], ["Huy", "Yarı agresif, avcı"], ["Beslenme", "Etçil"], ["Üreme", "Mağara/substrat yumurtlayıcısı"], ["Köken", "Güney Amerika"], ["Özellikler", "Avcı, Küçük Pike"]]'::jsonb,array['pike cichlid regani','crenicichla regani','regani pike','dwarf pike cichlid','pike ciklet']::text[],true,'published'),
('crenicichla-compressiceps','Pike Cichlid Compressiceps','Crenicichla compressiceps','guney-amerika','fish','Zor','Agresif, avcı','Kompakt boylu fakat aktif ve avcı bir cüce pike cikletidir. Güçlü akıntı ve yüksek oksijenli suya uyumlu popülasyonlarıyla bilinir.','[["Yetişkin boy", "10 cm"], ["Sıcaklık", "24–29 °C"], ["pH", "5.5–7.5"], ["Min. akvaryum", "120 L"], ["Huy", "Agresif, avcı"], ["Beslenme", "Etçil"], ["Üreme", "Mağara/substrat yumurtlayıcısı"], ["Köken", "Güney Amerika"], ["Özellikler", "Avcı, Nadir Tür"]]'::jsonb,array['pike cichlid compressiceps','crenicichla compressiceps','compressiceps pike','dwarf pike','crenicichla']::text[],true,'published'),
('crenicichla-saxatilis','Pike Cichlid Saxatilis','Crenicichla saxatilis','guney-amerika','fish','Orta','Agresif, avcı','Altın-kahverengi gövdesi ve yan lekeleriyle tanınan orta boy bir pike ciklettir. Küçük balıkları avlayabilir ve çiftler üremede sertleşebilir.','[["Yetişkin boy", "20 cm"], ["Sıcaklık", "23–28 °C"], ["pH", "5.5–7.5"], ["Min. akvaryum", "250 L"], ["Huy", "Agresif, avcı"], ["Beslenme", "Etçil"], ["Üreme", "Mağara/substrat yumurtlayıcısı"], ["Köken", "Güney Amerika"], ["Özellikler", "Avcı, Bölgeci"]]'::jsonb,array['pike cichlid saxatilis','crenicichla saxatilis','saxatilis pike','pike cichlid','crenicichla']::text[],true,'published'),
('acarichthys-heckelii','Acarichthys Heckelii','Acarichthys heckelii','guney-amerika','fish','Orta','Yarı agresif, sosyal','Uzayan yüzgeçleri ve inci benzeri benekleriyle dikkat çeken iri bir geophagine ciklettir. Kum tabanı ve geniş yüzme alanı ister; üreme için tünel/oyuk kullanabilir.','[["Yetişkin boy", "20 cm"], ["Sıcaklık", "24–30 °C"], ["pH", "5.5–7.5"], ["Min. akvaryum", "300 L"], ["Huy", "Yarı agresif, sosyal"], ["Beslenme", "Omnivor, bentik omurgasız ağırlıklı"], ["Üreme", "Tünel/mağara yumurtlayıcısı"], ["Köken", "Güney Amerika"], ["Özellikler", "Kum Eleyen, Renkli"]]'::jsonb,array['acarichthys heckelii','heckelii','threadfin acara','heckel acara']::text[],false,'published'),
('guianacara-stergiosi','Guianacara Stergiosi','Guianacara stergiosi','guney-amerika','fish','Orta','Yarı agresif, çift döneminde bölgeci','Guyana kalkanı drenajlarından gelen, bantlı deseni ve güçlü ebeveyn davranışıyla tanınan orta boy bir geophagine ciklettir.','[["Yetişkin boy", "12 cm"], ["Sıcaklık", "24–29 °C"], ["pH", "5.0–7.5"], ["Min. akvaryum", "150 L"], ["Huy", "Yarı agresif, çift döneminde bölgeci"], ["Beslenme", "Omnivor"], ["Üreme", "Substrat yumurtlayıcısı, ebeveyn bakımı"], ["Köken", "Güney Amerika"], ["Özellikler", "Ebeveyn Bakımı, Nadir Tür"]]'::jsonb,array['guianacara stergiosi','stergiosi','guianacara','banded cichlid']::text[],true,'published'),
('krobia-guianensis','Guyana Cichlid','Krobia guianensis','guney-amerika','fish','Orta','Yarı agresif','Görece sakin karakteri ve doğal görünümlü renkleriyle Guyana bölgesinin ilgi çekici orta boy cikletidir. Çiftler yavrularını aktif biçimde korur.','[["Yetişkin boy", "12 cm"], ["Sıcaklık", "23–28 °C"], ["pH", "5.5–7.5"], ["Min. akvaryum", "150 L"], ["Huy", "Yarı agresif"], ["Beslenme", "Omnivor"], ["Üreme", "Substrat yumurtlayıcısı, ebeveyn bakımı"], ["Köken", "Güney Amerika"], ["Özellikler", "Ebeveyn Bakımı, Nadir Tür"]]'::jsonb,array['krobia guianensis','krobia','guyana cichlid','guianensis']::text[],true,'published'),
('geophagus-brasiliensis','Pearl Cichlid','Geophagus brasiliensis','guney-amerika','fish','Orta','Agresif, bölgeci','Güneydoğu Güney Amerika kökenli, inci benzeri mavi benekleriyle tanınan dayanıklı ve bölgeci bir ciklettir. Güncel sınıflandırmalarda Geophagus dışına taşınması tartışılan gruptadır.','[["Yetişkin boy", "25 cm"], ["Sıcaklık", "18–28 °C"], ["pH", "6.0–8.0"], ["Min. akvaryum", "300 L"], ["Huy", "Agresif, bölgeci"], ["Beslenme", "Omnivor"], ["Üreme", "Substrat yumurtlayıcısı, çift ebeveyn bakımı"], ["Köken", "Güney Amerika"], ["Özellikler", "Dayanıklı, İri Yapılı"]]'::jsonb,array['geophagus brasiliensis','pearl cichlid','inci ciklet','brasiliensis']::text[],false,'published')
